import React from "react";
import { Link, useLocation } from "react-router-dom";

function Navbar() {
  const location = useLocation();

  return (
    <nav style={styles.nav}>
      {/* Logo */}
      <h2 style={styles.logo}>DocBook</h2>

      {/* Links */}
      <div style={styles.links}>
        <Link
          to="/"
          style={
            location.pathname === "/" ? styles.activeLink : styles.link
          }
        >
          Doctors
        </Link>

        <Link
          to="/appointments"
          style={
            location.pathname === "/appointments"
              ? styles.activeLink
              : styles.link
          }
        >
          My Appointments
        </Link>
      </div>

      {/* Auth Buttons */}
      <div>
        <Link to="/login" style={styles.loginBtn}>
          Login
        </Link>
      </div>
    </nav>
  );
}

const styles = {
  nav: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "12px 30px",
    background: "#ffffff",
    boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
  },
  logo: {
    color: "#1976d2",
    margin: 0,
  },
  links: {
    display: "flex",
    gap: "20px",
  },
  link: {
    textDecoration: "none",
    color: "#333",
    fontWeight: "500",
  },
  activeLink: {
    textDecoration: "none",
    color: "#1976d2",
    fontWeight: "600",
    borderBottom: "2px solid #1976d2",
  },
  loginBtn: {
    padding: "6px 14px",
    background: "#1976d2",
    color: "#fff",
    borderRadius: "5px",
    textDecoration: "none",
  },
};

export default Navbar;
